public class {{FeatureName}}Handler : IRequestHandler<{{FeatureName}}{{Type}}, {{FeatureName}}Response>
{
    {{InjectFields}}

    public {{FeatureName}}Handler
    (
        {{CtorParams}}
    )
    {
        {{AssignFields}}
    }

    #region Implementation of IRequestHandler<in {{FeatureName}}{{Type}}, {{FeatureName}}Response>

    public async Task<{{FeatureName}}Response> Handle({{FeatureName}}{{Type}} request, CancellationToken cancellationToken)
    {
        var functionName = $"{nameof({{FeatureName}}Handler)} =>";
        _logger.LogInformation(functionName);
        var response = new {{FeatureName}}Response();

        try
        {

            response.Ok();
        }
        catch (Exception exception)
        {
            exception.LogError(_logger, functionName);
            response.WithStatus(HttpStatusCode.InternalServerError);
        }

        return response;
    }

    #endregion
}

